name: Deploy to preprd_final

on:
  push:
    branches:
      - preprod_final
  workflow_dispatch:

jobs:
  deploy:
    runs-on: [self-hosted, jenkins-server]

    steps:
      - name: Checkout code
        uses: actions/checkout@v4

      - name: Run remote script
        run: |
          ssh -o StrictHostKeyChecking=no ubuntu@10.1.106.143 << EOF
          #!/bin/bash
          set -e
          set -x

          cd /var/www/ramfin/AWS/
          git reset --hard origin/preprod_final
          git pull origin preprod_final

          cd /var/www/ramfin/AWS/loanapply/
          cp -r /home/ubuntu/v/vendor .
          cp -r /home/ubuntu/v/composer.json .
          cp -r /home/ubuntu/v/composer.lock .
          cp -r /home/ubuntu/v/satging/.htaccess .

          cd /var/www/ramfin/AWS/pay-now
          cp -r /home/ubuntu/v/.htaccess .
          sed -i 's/www\.ramfincorp\.com/preprod.ramfincorp.co.in/g' /var/www/ramfin/AWS/pay-now/index.php

          cd /var/www/ramfin/AWS/
          cp -r /home/ubuntu/v/robots.txt .

          # Better permissions (optional, adjust as needed)

          sudo chmod -R 777 /var/www/ramfin/AWS

          git log | head -18
          echo "Deployment to pre-prod completed successfully"
          EOF



