    public function call_api_curl($url, $data, $auth, $leadID, $customerID, $userID, $idemKey='') {
        try {

            // Initialize header data array
            $header_data = [
                "authorization: $auth",
                "cache-control: no-cache",
                "content-type: application/json"
            ];

            // Add the X-Payout-Idempotency header if $idemKey is provided
            if (!empty($idemKey)) {
                $header_data[] = "X-Payout-Idempotency: $idemKey";
            }

            $curl = curl_init();
            curl_setopt_array($curl, array(
                CURLOPT_URL => $url,
                CURLOPT_RETURNTRANSFER => true,
                CURLOPT_ENCODING => "",
                CURLOPT_MAXREDIRS => 10,
                CURLOPT_TIMEOUT => 30,
                CURLOPT_HTTP_VERSION => CURL_HTTP_VERSION_1_1,
                CURLOPT_CUSTOMREQUEST => "POST",
                CURLOPT_POSTFIELDS => $data,
                CURLOPT_HTTPHEADER => $header_data,
            ));

            $response = curl_exec($curl);
            curl_close($curl);

            $this->disbursal_logs($customerID, $leadID, 'api call', '', $userID, $url.'-'.$data , $response);

            return $response;

        } catch (\Exception $e) {

           $this->disbursal_logs($customerID, $leadID, 'api call', $e, $userID, $url.'-'.$data, null);

        }
    }
