DB::statement("SET SESSION sql_mode=(SELECT REPLACE(@@sql_mode,'ONLY_FULL_GROUP_BY',''))");
⋮----
/*	$query = "WITH CollectionDetails" . $d . " AS (
	SELECT
    	col.collectionID,
    	col.leadID,
    	col.loanNo,
    	col.status,
    	col.excess_amount,
    	col.principal_amount AS principal_amount,
    	col.collected_principal AS collected_principal,
    	col.collected_interest AS collected_interest,
    	col.collected_penality AS collected_penality,
    	col.collectedDate AS collectedDate,
    	col.referenceNo AS referenceNo,
    	CONCAT(MONTHNAME(col.collectedDate), ' ', YEAR(col.collectedDate)) AS CollectedMonth,
    	col.collectedAmount AS CollectedAmount,
    	DATEDIFF(col.collectedDate, a.repayDate) AS PaymentDPDs,
    	col.orderID AS OrderIDs,
    	col.collectedMode,
    	(CASE WHEN collectedMode='Waive Off' or collectedMode='DISCOUNT' THEN collectedAmount else 0 end) Waive_off_amount,
    	(CASE WHEN collectedMode IN ('Waive Off', 'DISCOUNT') THEN discount_waiver_amount ELSE 0 END) AS discount_waiver_amount,
    	(CASE WHEN collectedMode IN ('Waive Off', 'DISCOUNT') THEN collectedDate ELSE NULL END) AS WaiverDate,
    	(SELECT SUM(CASE WHEN collectedMode NOT IN ('Waive Off','DISCOUNT') THEN collectedAmount ELSE 0 END)
     	FROM collection WHERE leadID=col.leadID AND collectionStatus='Approved' and collectedDate<= '" . $datas . "') AS actual_collected_amount,
    	(SELECT SUM(collectedAmount) FROM collection WHERE leadID=col.leadID AND collectionStatus='Approved' AND collectionID<=col.collectionID AND collectedDate<= '" . $datas . "') AS TotalCollectedAmount,
    	(SELECT MAX(collectedDate) FROM collection WHERE leadID=col.leadID AND collectionStatus='Approved' AND collectedDate<= '" . $datas . "' ) AS MaxCollectedDate,
    	(SELECT MAX(collectedDate) FROM collection WHERE leadID=col.leadID AND collectionStatus='Approved' AND collectedDate<= '" . $datas . "' AND (status='closed' OR status='Settlement')) AS MaxClosedOrSettlementDate,
    	(SELECT status FROM collection WHERE leadID=col.leadID AND collectionStatus='Approved' AND collectedDate<= '" . $datas . "' order by collectedDate,collectionID desc limit 1) AS lead_status,
        (CASE WHEN DATEDIFF('" . $datas . "',a.repayDate) <=0 THEN '(<=0)'
			  WHEN DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 1 AND 30 THEN '(1-30)'
              WHEN DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 31 and 60 THEN '(31-60)'
              WHEN DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 61 and 90 THEN '(61-90)'
              WHEN DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 91 and 180 THEN '(91-180)'
              WHEN DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 181 and 365 THEN '(181-365)'
              WHEN DATEDIFF('" . $datas . "',a.repayDate) >365 THEN '(>365)'
			  ELSE '' END) collection_dpd,
    	collected_penality AS penalCharges
	FROM
    	collection col
	JOIN
    	approval a ON col.leadID = a.leadID
	WHERE
    	col.collectionStatus = 'Approved' and col.collectedDate<= '" . $datas . "' order by collectionID asc
),
RefundDetails" . $d . " AS (
	SELECT
    	leadID,
    	loanNo,
    	collectedAmount AS `Refunded Amount`,
    	collectedDate AS `Refund Date`
	FROM
    	collection
	WHERE
    	collectionStatus = 'Approved-refunded' and collectedDate <= '" . $datas . "'
),
CalculatedAmounts" . $d . " AS (
	SELECT
    	l.leadID,
    	l.loanNo,
    	l.disbursalAmount,
    	col.collectionID,
    	ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)) AS RepayAmount,
    	ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)) - l.disbursalAmount AS InterestAmount,
    	COALESCE(col.TotalCollectedAmount, 0) AS TotalCollectedAmount,
    	(CASE WHEN LEAST(l.disbursalAmount, COALESCE(col.TotalCollectedAmount, 0))=col.TotalCollectedAmount THEN col.collectedAmount ELSE (CASE WHEN (col.collectedAmount-(col.TotalCollectedAmount-l.disbursalAmount))>0 THEN (col.collectedAmount-(col.TotalCollectedAmount-l.disbursalAmount)) else 0 END) END) AS PrincipalCollected,
    	(CASE WHEN LEAST(ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)) - l.disbursalAmount, GREATEST(COALESCE(col.TotalCollectedAmount, 0) - l.disbursalAmount - COALESCE(col.collectedAmount,0), 0))=(ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure))  - l.disbursalAmount) Then 0 ELSE LEAST(ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)) - l.disbursalAmount, GREATEST(COALESCE(col.TotalCollectedAmount, 0) - l.disbursalAmount, 0)) END) AS InterestCollected,
    	(CASE WHEN GREATEST(COALESCE(col.TotalCollectedAmount, 0) - ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)) - COALESCE(col.collectedAmount,0), 0)>0 THEN col.collectedAmount ELSE GREATEST(COALESCE(col.TotalCollectedAmount, 0) - ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)),0) END) AS PenalInterest,
    	GREATEST(l.disbursalAmount - COALESCE(col.TotalCollectedAmount, 0), 0) AS POS,
    	IFNULL((SELECT principal_amount FROM collection WHERE col.leadID=leadID AND collectionStatus='Approved' AND collectedDate < '" . $datas . "' ORDER BY collectionID DESC LIMIT 1), l.disbursalAmount) AS POSIPC,

    	CASE
        	WHEN col.MaxClosedOrSettlementDate IS NOT NULL THEN DATEDIFF(col.MaxClosedOrSettlementDate, l.disbursalDate)
        	ELSE DATEDIFF(NOW(), l.disbursalDate)
    	END AS ActualTenureDays,
    	CASE
    	WHEN (l.disbursalAmount > (col.actual_collected_amount))
        	THEN (CASE WHEN (l.disbursalAmount - (col.actual_collected_amount)) >= col.discount_waiver_amount
                	THEN col.discount_waiver_amount
                	ELSE (l.disbursalAmount - (col.actual_collected_amount))
        	END)
    	ELSE 0
	END AS `principal_waive_off`
	FROM
    	loan l
	LEFT JOIN
    	approval a ON l.leadID = a.leadID
	LEFT JOIN
    	CollectionDetails" . $d . " col ON l.leadID = col.leadID AND l.loanNo = col.loanNo
	WHERE
    	l.status = 'Disbursed' and l.disbursalDate <= '" . $datas . "'
),
OverdueAmounts" . $d . " AS (
	SELECT
    	l.leadID,
    	l.loanNo,
    	l.disbursalAmount AS OverduePrincipal,
    	ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure)) - l.disbursalAmount AS OverdueInterest
	FROM
    	loan l
	LEFT JOIN
    	approval a ON l.leadID = a.leadID
	LEFT JOIN
    	leads le ON l.leadID = le.leadID
	WHERE
    	le.status = 'part payment'
),
DueAmounts" . $d . " AS (
	SELECT
    	l.leadID,
    	l.loanNo,
    	ROUND(
        	ROUND(l.disbursalAmount + (l.disbursalAmount * a.roi / 100 * a.tenure))
        	+ (l.disbursalAmount * 1.25 / 100 * DATEDIFF('" . $datas . "', a.repayDate))
        	- SUM(CASE WHEN co.collectionStatus = 'Approved' THEN co.collectedAmount ELSE 0 END)
    	) AS DueAmount,
     	DATEDIFF(NOW(), a.repayDate) AS CurrentTenure
	FROM
    	loan l
	LEFT JOIN
    	approval a ON l.leadID = a.leadID
	LEFT JOIN
    	collection co ON l.leadID = co.leadID AND l.loanNo = co.loanNo
	LEFT JOIN
    	leads le ON l.leadID = le.leadID
	WHERE
    	(le.status = 'Disbursed' AND a.repayDate < '" . $datas . "')
    	OR le.status = 'part payment'
	GROUP BY
    	l.leadID, l.loanNo, l.disbursalAmount, a.roi, a.tenure, a.repayDate
),
AgeCategorized" . $d . " AS (
	SELECT
    	c.customerID,
    	TIMESTAMPDIFF(YEAR, c.dob, c.createdDate) AS age,
    	CASE
        	WHEN TIMESTAMPDIFF(YEAR, c.dob, c.createdDate) BETWEEN 20 AND 29 THEN '20-29'
        	WHEN TIMESTAMPDIFF(YEAR, c.dob, c.createdDate) BETWEEN 30 AND 39 THEN '30-39'
        	WHEN TIMESTAMPDIFF(YEAR, c.dob, c.createdDate) BETWEEN 40 AND 49 THEN '40-49'
        	WHEN TIMESTAMPDIFF(YEAR, c.dob, c.createdDate) BETWEEN 50 AND 59 THEN '50-59'
        	ELSE '60+'
    	END AS AgeBracket
	FROM customer c
),
TenureCategorized" . $d . " AS (
	SELECT
    	a.leadID,
    	a.tenure,
    	CASE
        	WHEN a.tenure BETWEEN 1 AND 15 THEN '1-15 days'
        	WHEN a.tenure BETWEEN 16 AND 30 THEN '16-30 days'
        	ELSE '30+ days'
    	END AS TenureBin
	FROM approval a
),
DisbursalAmountCategorized" . $d . " AS (
	SELECT
    	l.loanID,
    	l.disbursalAmount,
    	CASE
        	WHEN l.disbursalAmount < 5000 THEN '<5000'
        	WHEN l.disbursalAmount BETWEEN 5000 AND 9999 THEN '5000-10000'
        	WHEN l.disbursalAmount BETWEEN 10000 AND 19999 THEN '10000-20000'
        	WHEN l.disbursalAmount BETWEEN 20000 AND 29999 THEN '20000-30000'
        	WHEN l.disbursalAmount BETWEEN 30000 AND 39999 THEN '30000-40000'
        	WHEN l.disbursalAmount BETWEEN 40000 AND 49999 THEN '40000-80000'
        	WHEN l.disbursalAmount BETWEEN 50000 AND 59999 THEN '50000-60000'
        	WHEN l.disbursalAmount BETWEEN 60000 AND 69999 THEN '60000-70000'
        	WHEN l.disbursalAmount BETWEEN 70000 AND 79999 THEN '70000-80000'
        	WHEN l.disbursalAmount BETWEEN 80000 AND 89999 THEN '80000-90000'
        	WHEN l.disbursalAmount BETWEEN 90000 AND 99999 THEN '90000-100000'
        	WHEN l.disbursalAmount BETWEEN 100000 AND 149999 THEN '100000-180000'
        	ELSE '>180000'
    	END AS DisbursalBracket
	FROM loan l
),
IncomeRanking" . $d . " AS (
	SELECT
    	le.leadID,
    	le.monthlyIncome,
    	CASE
        	WHEN le.monthlyIncome < 25000 THEN '<25000'
        	WHEN le.monthlyIncome BETWEEN 25000 AND 29999 THEN '25000-30000'
        	WHEN le.monthlyIncome BETWEEN 30000 AND 60000 THEN '30000-60000'
        	WHEN le.monthlyIncome BETWEEN 60000 AND 89999 THEN '60000-90000'
        	WHEN le.monthlyIncome BETWEEN 90000 AND 99999 THEN '90000-100000'
        	WHEN le.monthlyIncome BETWEEN 100000 AND 149999 THEN '100000-150000'
        	ELSE '180000+'
    	END AS IncomeBracket
	FROM leads le
	WHERE le.monthlyIncome IS NOT NULL
),
ROICategorized" . $d . " AS (
	SELECT
    	a.leadID,
    	a.roi,
    	CASE
        	WHEN a.roi < 0.8 THEN '<0.8'
        	WHEN a.roi BETWEEN 0.8 AND 0.89 THEN '0.8-0.9'
        	WHEN a.roi BETWEEN 0.9 AND 0.99 THEN '0.9-1'
        	WHEN a.roi = 1.00 THEN '1'
        	ELSE '>1'
    	END AS ROIBracket
	FROM approval a
),
Loan_POS_CTE" . $d . " AS (
	SELECT
    	l.loanNo,
    	COALESCE(
        	(SELECT POS
         	FROM CalculatedAmounts" . $d . " ca
         	WHERE ca.loanNo = l.loanNo
         	ORDER BY ca.collectionID DESC
         	LIMIT 1),
        	0) AS LastPOS
	FROM
    	loan l
	WHERE
    	l.status = 'Disbursed' and l.disbursalDate <= '" . $datas . "'
)

SELECT
	sum(CASE WHEN ifnull(col.TotalCollectedAmount,0)=ifnull(col.collectedAmount,0) && (from_unixtime(unix_timestamp(l.disbursalDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m')) THEN l.disbursalAmount ELSE 0 END) AS 'DisbursalAmount',
	CONCAT(MONTHNAME(l.disbursalDate), ' ', YEAR(l.disbursalDate)) AS `DisbursalMonthYear`,
	sum(CASE WHEN (from_unixtime(unix_timestamp(col.collectedDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m')) THEN COALESCE(col.collectedAmount, 0) ELSE 0 END) AS `TotalCollectedAmount`,
	sum(CASE WHEN (from_unixtime(unix_timestamp(col.collectedDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m')) THEN (CASE WHEN (CASE WHEN le.ipc=1 THEN col.collected_principal ELSE ca.PrincipalCollected END)>l.disbursalAmount THEN l.disbursalAmount
	ELSE (CASE WHEN le.ipc=1 THEN col.collected_principal ELSE ca.PrincipalCollected END) END) ELSE 0 END ) AS 'PrincipalCollected_ipc',
	sum(CASE WHEN le.ipc=1 THEN col.collected_interest ELSE (CASE WHEN ca.InterestCollected=0 Then 0 else  ca.InterestCollected- ifnull((select InterestCollected from CalculatedAmounts" . $d . " cc where ca.leadID = cc.leadID AND cc.loanNo = ca.loanNo AND cc.collectionID < ca.collectionID order by cc.collectionID desc limit 1),0) END) END) AS 'DDInterestAmount',
    sum(CASE WHEN le.ipc=1 THEN col.collected_penality ELSE ca.PenalInterest END) AS 'LateFeeCollected_ipc',
    sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate) <=0 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `lessThanzeroDPD`,
	sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 1 AND 30 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `oneToThirtyDPD`,
    sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 31 AND 60 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `thirtyToSixtyDPD`,
    sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 61 AND 90 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `sixtyToNinetyDPD`,
    sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 91 AND 180 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `ninetyToOnetwentyDPD`,
    sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate) BETWEEN 181 AND 365 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `(181-365)`,
    sum(CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && DATEDIFF('" . $datas . "',a.repayDate)>365 THEN (CASE WHEN col.TotalCollectedAmount<>col.collectedAmount THEN 0 ELSE lc.LastPOS END) ELSE 0 END) `>365`,
	sum(CASE WHEN le.ipc=1 THEN ca.POSIPC ELSE ca.POS END) AS `Overdue Principal`,
	sum((CASE WHEN IFNULL(MaxClosedOrSettlementDate,0)=0 && ifnull(col.TotalCollectedAmount,0)=ifnull(col.collectedAmount,0) THEN lc.LastPOS ELSE 0 END)) AS `Principal Outstanding (POS)`,
    sum(CASE WHEN col.collection_dpd='(<=0)' && (from_unixtime(unix_timestamp(col.collectedDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m'))  THEN (CASE WHEN le.ipc=1 THEN col.collected_principal ELSE ca.PrincipalCollected END) ELSE 0 END) `W-O_coll_<=0`,
    sum(CASE WHEN col.collection_dpd='(1-30)' && (from_unixtime(unix_timestamp(col.collectedDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m'))  THEN (CASE WHEN le.ipc=1 THEN col.collected_principal ELSE ca.PrincipalCollected END) ELSE 0 END) `W-O_coll_1_30`,
    sum(CASE WHEN col.collection_dpd='(31-60)' && (from_unixtime(unix_timestamp(col.collectedDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m'))  THEN (CASE WHEN le.ipc=1 THEN col.collected_principal ELSE ca.PrincipalCollected END) ELSE 0 END) `W-O_coll_31_60`,
    sum(CASE WHEN col.collection_dpd='(61-90)' && (from_unixtime(unix_timestamp(col.collectedDate),'%Y-%m')=from_unixtime(unix_timestamp('" . $datas . "'),'%Y-%m'))  THEN (CASE WHEN le.ipc=1 THEN col.collected_principal ELSE ca.PrincipalCollected END) ELSE 0 END) `W-O_coll_61_90`,
