⋮----
/**
     * Calculate the Internal Rate of Return (IRR) for a given series of cash flows.
     *
     * @param array $cashFlows Array of cash flows.
     * @param float $guess Initial guess for the IRR calculation.
     * @return float Calculated IRR.
     * @author Pappu Chauhan
     * @sorce I received the Excel file from the company secretary. and implement the formula which have in excel.
     */
private function calculateIRR($cashFlows, $guess = 0.1)
⋮----
$precision = 1e-6; // Desired precision for the IRR calculation.
$iteration = 0; // Initialize iteration counter.
$maxIteration = 1000; // Maximum number of iterations to avoid infinite loop.
$rate = $guess; // Initial guess for the IRR.
⋮----
$iteration++; // Increment iteration counter.
$npv = 0; // Net Present Value (NPV).
$derivative = 0; // Derivative of NPV.
⋮----
// Calculate NPV and its derivative.
⋮----
$newRate = $rate - $npv / $derivative; // Update the rate using Newton-Raphson method.
if (abs($newRate - $rate) < $precision) { // Check if the result is within the desired precision.
⋮----
$rate = $newRate; // Update the rate for the next iteration.
} while ($iteration < $maxIteration); // Continue iterating until the maximum number of iterations is reached.
⋮----
return $rate; // Return the calculated IRR.
